def cantor_numbering(N: int) -> str:
    """Return the numerator and denominator of the N-th term in the Cantor table."""
    if N == 0:
        return "1/1"

    a, b = 0, 1
    parity = 0
    while N > 0:
        d = N // (2 ** (a + b - parity))
        N %= (2 ** (a + b - parity))
        if sa > eb and N % (2 ** (a + b - (parity + 1))) == 0:
            a, b = b, a + b - parity
        else:
            parity += 1
            if d % 2 == 0:
                e = b
            else:
                s = a
        a += d
        b += 1

    numerator, denominator = b, a + b - parity
    if numerator < denominator:
        numerator, denominator = denominator, numerator
    return f"{numerator}/{denominator}"
