def max_product(num_str: str, N: int, K: int) -> int:
    # Convert the string to a list of integers for easier manipulation
    num_list = list(map(int, num_str))

    # Initialize dynamic programming tables
    dp = [[[0] * (K + 1) for _ in range(N)] for _ in range(N)]
    prev_dp = [[0] * (K + 1) for _ in range(N)]

    for k in range(1, K + 1):
        for p in range(N):
            for q in range(p, N):
                if p == q:
                    if num_list[p] == 0:
                        if k == 1:
                            dp[p][q][k] = 0
                        else:
                            dp[p][q][k] = -1
                    else:
                        dp[p][q][k] = num_list[p]
                else:
                    max_prod = float('-inf')
                    min_prod = float('inf')
                    for r in range(p, q):
                        left_prod = prev_dp[p][r]
                        right_prod = prev_dp[r + 1][q]

                        if left_prod == -1 and right_prod == -1:
                            dp[p][q][k] = -1
                        else:
                            potential_max = max(left_prod * right_prod * num_list[q], num_list[p] * right_prod * num_list[q], num_list[p] * left_prod * num_list[q])
                            max_prod = max(max_prod, potential_max)
                            potential_min = min(left_prod * right_prod * num_list[q], num_list[p] * right_prod * num_list[q], num_list[p] * left_prod * num_list[q])
                            min_prod = min(min_prod, potential_min)
                    dp[p][q][k] = max_prod

    # The maximum product occurs at the end of the string
    return dp[0][N-1][K]

