def calculate_arrangements(n, m, a):
    mod = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There is one way to arrange 0 pots for any number of flowers
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the dp table
    for flower_type in range(1, n + 1):
        for pots in range(1, m + 1):
            for pots_used in range(1, pots + 1):
                if pots_used > a[flower_type - 1]:
                    break
                dp[flower_type][pots] = (dp[flower_type - 1][pots] + dp[flower_type][pots - pots_used]) % mod

    return dp[n][m]
